program.compute:
pool = read('/input/options')
pool = sorted(pool, key=lambda row: row['id'])
if goal['order_by']:
    pool = sorted(pool, key=lambda row: [row[field] for field in goal['order_by']])
result = read('/output/selection')
if result is None or not valid(result):
    result = None
    for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
        for group in combinations(pool, count):
            proposal = [entry['id'] for entry in group]
            if valid(proposal):
                result = proposal
                break
        if result is not None:
            break

program.effects:
if result is not None:
    write('/output/selection', result)
    if status('report') != 'sent':
        send('report', 'team', result)
else:
    # no valid selection found, do not write or send
    pass
if exists('/tmp/cache'):
    delete('/tmp/cache')

